                triggers.append((r, c))

    # Mark all bg cells adjacent to triggers
    from collections import deque
    to_fill = deque()
    for r, c in triggers:
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == bg:
                to_fill.append((nr, nc))

    while to_fill:
        r, c = to_fill.popleft()
        result[r][c] = 1
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
